// ONE FLOW OF TEXT (operator 2026-10-08, five complaints about the chat of a goal run: "each block message on the
// chat has too distinct a design, like report, the task prompt … the rest should appear like one text, a pretty
// organized flow of text" · "the prompt generated by Heimdall … shows the same design as the user prompt, it should
// have a difference. Like a task view" · "the buttons, telemetry, pricing stats … is shown all the time. It should
// collapse … on mouse over it expands … expanded by default only at the end of everything").
//
// Three small pieces, no knowledge of the chat's data model (the pane hands them what to say):
//   FlowBlock  — a mono label + a shared left rule + one body size. Everything the AGENT side of the thread says
//                (the task, a reply, the report, a note) wears it, so the thread reads as one organised text.
//                Only the human's own bubble keeps a background.
//   TaskCard   — the prompt Heimdall organised from the human's ask, drawn as a task view (left, boxed, a header and
//                the plan's tasks as a checklist) — never as a second human bubble.
//   ReplyMeta  — the buttons, the trace, the telemetry and the price under an answer, folded to ONE dim line. Hover
//                previews it in a window, a click pins it open; it is open by default only on the last block of an
//                idle thread, where the line is the thread's TOTAL.
import * as React from "react";
import { createPortal } from "react-dom";
import { C, mono } from "@/loki/theme";
import { BubbleBody } from "@/loki/chat/chat-thread";

// ── FlowBlock ────────────────────────────────────────────────────────────────────────────────────
export type FlowKind = "task" | "result" | "agent" | "note" | "story";
const RULE: Record<FlowKind, string> = { task: C.brand, result: C.ok, agent: C.border, note: C.border, story: C.border };
/** The one body size of the flow — replies, the task, the report, notes all read at it. */
export const FLOW_SIZE = 13;

export function FlowBlock({ kind, label, meta, tone, testId, pulse, children }: { kind: FlowKind; /** the small mono word that names the block: task · result · agent */ label?: string; /** dim text after the label (engine · model · time) */ meta?: string; tone?: "ok" | "warn" | "bad" | "dim"; testId?: string; pulse?: boolean; children: React.ReactNode }) {
  const rule = tone === "bad" ? C.bad : tone === "warn" ? C.warn : RULE[kind];
  return (
    <div data-testid={testId} data-flow={kind} style={{ display: "flex", flexDirection: "column", gap: 2, margin: "0 0 10px", paddingLeft: 10, borderLeft: `2px solid color-mix(in oklab, ${rule} ${kind === "agent" || kind === "note" || kind === "story" ? 70 : 60}%, transparent)`, animation: pulse ? "antilokiPulse 1.3s ease-in-out infinite" : undefined }}>
      {(label || meta) && (
        <div style={{ fontFamily: mono, fontSize: 9.5, letterSpacing: 0.6, color: C.dim, display: "flex", gap: 6, alignItems: "baseline", flexWrap: "wrap" }}>
          {label && <span style={{ color: kind === "task" ? C.brand : tone === "bad" ? C.bad : kind === "result" ? C.ok : C.muted, textTransform: "uppercase", fontWeight: 700 }}>{label}</span>}
          {meta && <span>{meta}</span>}
        </div>
      )}
      <div style={{ fontSize: FLOW_SIZE, lineHeight: 1.55, color: C.fg, wordBreak: "break-word", minWidth: 0 }}>{children}</div>
    </div>
  );
}

/** A reply, as flowing text: the same markdown (or lens verdict) the bubble drew, without the bubble. */
export function FlowReply({ text, engine, model, ts, streaming }: { text: string; engine?: string; model?: string; ts?: string; streaming?: boolean }) {
  const meta = streaming ? `${engine ?? ""} · thinking…` : [engine, model, ts].filter(Boolean).join(" · ");
  return <FlowBlock kind="agent" label="agent" meta={meta} testId="flow-reply" pulse={streaming}><BubbleBody text={text} /></FlowBlock>;
}

// ── TaskCard ─────────────────────────────────────────────────────────────────────────────────────
export type TaskLine = { id: string; title: string; status: string };
const taskMark = (s: string) => (s === "done" ? { g: "✓", c: C.ok } : s === "failed" || s === "blocked" ? { g: "✗", c: C.bad } : s === "running" || s === "verifying" ? { g: "◐", c: C.warn } : s === "skipped" ? { g: "–", c: C.dim } : { g: "○", c: C.dim });

/** THE PROMPT HEIMDALL WROTE (operator 2026-10-08: "the prompt generated by Heimdall organizing the tasks is displaying,
 *  which is ok, but the UI shows the same design as the user prompt, it should have a difference. Like a task view on
 *  the chat."). Left-aligned and boxed where the human's is right-aligned and tinted; headed `⚡ Heimdall · task`; the plan's
 *  tasks as a checklist when the run is known. `long` folds the body to a few lines behind a ▸. */
export function TaskCard({ children, meta, ts, tasks = [], long = false, colors }: { children: React.ReactNode; meta?: string | null; ts?: string; tasks?: TaskLine[]; long?: boolean; colors?: { fg: string; dim: string; muted: string; border: string; accent: string; font?: string; mono?: string; radius?: number } }) {
  const [open, setOpen] = React.useState(false);
  const k = colors ?? { fg: C.fg, dim: C.dim, muted: C.muted, border: C.border, accent: C.brand };
  const m = k.mono ?? mono;
  const fold = long && !open;
  return (
    <div data-testid="task-card" data-from="heimdall" style={{ alignSelf: "flex-start", maxWidth: "94%", margin: "0 0 10px", padding: "6px 10px 7px", borderTop: `1px solid ${k.border}`, borderRight: `1px solid ${k.border}`, borderBottom: `1px solid ${k.border}`, borderLeft: `3px solid ${k.accent}`, borderRadius: k.radius ?? 8, display: "flex", flexDirection: "column", gap: 4 }}>
      <div style={{ fontFamily: m, fontSize: 9.5, letterSpacing: 0.6, color: k.dim, display: "flex", gap: 6, alignItems: "baseline", flexWrap: "wrap" }}>
        <span data-testid="task-card-head" style={{ color: k.accent, fontWeight: 700 }}>⚡ Heimdall · task</span>
        {meta && <span>{meta}</span>}{ts && <span>{ts}</span>}
      </div>
      <div data-testid="task-card-body" data-folded={fold ? "1" : "0"} style={{ fontFamily: k.font, fontSize: FLOW_SIZE - 0.5, lineHeight: 1.5, color: k.fg, whiteSpace: "pre-wrap", wordBreak: "break-word", ...(fold ? { maxHeight: "7.5em", overflow: "hidden" } : {}) }}>{children}</div>
      {long && <button data-testid="task-card-more" onClick={() => setOpen((o) => !o)} style={{ alignSelf: "flex-start", background: "transparent", border: "none", padding: 0, cursor: "pointer", fontFamily: m, fontSize: 10, color: k.muted }}>{open ? "▾ fold the task" : "▸ the whole task"}</button>}
      {tasks.length > 0 && (
        <div data-testid="task-card-list" style={{ display: "flex", flexDirection: "column", gap: 1, fontFamily: m, fontSize: 10.5, borderTop: `1px dashed ${k.border}`, paddingTop: 4 }}>
          {tasks.map((t) => { const mk = taskMark(t.status); return <div key={t.id} style={{ display: "flex", gap: 6, color: k.fg }}><span style={{ color: mk.c, width: 10 }}>{mk.g}</span><span style={{ minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{t.title}</span></div>; })}
        </div>
      )}
    </div>
  );
}

// ── the numbers behind the one line ──────────────────────────────────────────────────────────────
/** What an exchange cost and saved, read from the notes and the result it already holds. The serve's `audit` event carries the deterministic
 *  price (and the time and tokens); the `saving` note carries the same tokens at the frontier model's list price. */
export type ExMeta = { cost: number; ms: number; tokens: number; baseline: number; saved: number; tools: number; failed: number; error?: string; any: boolean };
type MetaSource = { tools: { error?: boolean }[]; notes: { chan?: string; audit?: { cost: number; ms: number; tokens: number }; saving?: { cost: number; baseline: number } }[]; result?: { cost: number; ms: number; error?: string } };
export function metaOf(x: MetaSource): ExMeta {
  let cost = 0, ms = 0, tokens = 0, baseline = 0, saved = 0, audits = 0;
  for (const n of x.notes) {
    if (n.audit) { cost += n.audit.cost; ms += n.audit.ms; tokens += n.audit.tokens; audits += 1; }
    if (n.saving) { baseline += n.saving.baseline; saved += Math.max(0, n.saving.baseline - n.saving.cost); }
  }
  // a session turn also ends with a `result`; the audit's price is the serve's own arithmetic, so it wins when it exists
  if (!audits && x.result) { cost = x.result.cost; ms = x.result.ms; }
  const failed = x.tools.filter((t) => t.error).length;
  return { cost, ms, tokens, baseline, saved, tools: x.tools.length, failed, error: x.result?.error, any: cost > 0 || ms > 0 || baseline > 0 };
}
/** The whole thread's numbers: costs, times and savings add; each exchange counts once. Pure — tested. */
export function sumMeta(list: ExMeta[]): ExMeta & { turns: number } {
  const t = list.reduce((a, m) => ({ cost: a.cost + m.cost, ms: a.ms + m.ms, tokens: a.tokens + m.tokens, baseline: a.baseline + m.baseline, saved: a.saved + m.saved, tools: a.tools + m.tools, failed: a.failed + m.failed, error: a.error ?? m.error, any: a.any || m.any }), { cost: 0, ms: 0, tokens: 0, baseline: 0, saved: 0, tools: 0, failed: 0, error: undefined as string | undefined, any: false });
  return { ...t, turns: list.filter((m) => m.any).length };
}
const money = (n: number) => `$${n < 0.01 ? n.toFixed(4) : n < 0.1 ? n.toFixed(3) : n.toFixed(2)}`;
const secs = (ms: number) => (ms >= 1000 ? `${(ms / 1000).toFixed(1)} s` : `${Math.round(ms)} ms`);
/** `$0.011 · saved 90% · 4.1 s` — the one line an exchange folds to; "" when nothing is known yet. Pure — tested. */
export function metaLine(m: ExMeta): string {
  const parts: string[] = [];
  if (m.error) parts.push("failed");
  if (m.cost > 0) parts.push(money(m.cost));
  if (m.baseline > 0 && m.saved >= 0.00005) parts.push(`saved ${Math.round((m.saved / m.baseline) * 100)}%`);
  if (m.ms > 0) parts.push(secs(m.ms));
  if (m.tools > 0) parts.push(`${m.tools} tool${m.tools === 1 ? "" : "s"}${m.failed ? ` (${m.failed} failed)` : ""}`);
  return parts.join(" · ");
}
/** The same for the whole thread: `total · 3 turns · $0.043 · saved 88% · 21.0 s`. */
export function totalLine(t: ExMeta & { turns: number }): string {
  const body = metaLine({ ...t, tools: 0 });
  return `total · ${t.turns} turn${t.turns === 1 ? "" : "s"}${body ? ` · ${body}` : ""}`;
}

// ── ReplyMeta ────────────────────────────────────────────────────────────────────────────────────
type MetaColors = { dim: string; muted: string; fg: string; border: string; panel: string };
const LEAVE_MS = 160;

/** EVERYTHING UNDER THE ANSWER, FOLDED (operator 2026-10-08: "it should collapse because it is a little repetitive. And
 *  on mouse over it expands. The important is that they show expanded by default only at the end of everything counting
 *  all things, with a mouse-over window preview.").
 *
 *  One dim line. Hover → the same content in a window that follows the line (portalled, so no pane clips it); click →
 *  it opens in place and stays; click again folds it. `final` is the one block of an idle thread that starts open, and
 *  `totalLine` — given only then — becomes its line: the sum over every exchange, with this turn's own line under it. */
export function ReplyMeta({ line, totalLine: total, final = false, colors, font = mono, children }: { line: string; totalLine?: string | null; final?: boolean; colors?: MetaColors; font?: string; children: React.ReactNode }) {
  const k: MetaColors = colors ?? { dim: C.dim, muted: C.muted, fg: C.fg, border: C.border, panel: C.panel };
  const [pin, setPin] = React.useState<boolean | null>(null);   // what the operator chose by clicking; null = follow `final`
  const [hot, setHot] = React.useState(false);
  const open = pin ?? final;
  const trigger = React.useRef<HTMLButtonElement | null>(null);
  const leave = React.useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const [pos, setPos] = React.useState<{ left: number; top?: number; bottom?: number; width: number } | null>(null);
  const showPreview = hot && !open;
  React.useLayoutEffect(() => {
    if (!showPreview) { setPos(null); return; }
    const place = () => {
      const r = trigger.current?.getBoundingClientRect(); if (!r) return;
      const vw = window.innerWidth || 1024, vh = window.innerHeight || 768;
      const width = Math.min(560, vw - 16);
      const left = Math.max(8, Math.min(r.left, vw - width - 8));
      // below the line when there is room for a useful window, else above it
      setPos(vh - r.bottom > 280 ? { left, top: r.bottom + 4, width } : { left, bottom: Math.max(8, vh - r.top + 4), width });
    };
    place();
    window.addEventListener("resize", place); window.addEventListener("scroll", place, true);
    return () => { window.removeEventListener("resize", place); window.removeEventListener("scroll", place, true); };
  }, [showPreview]);
  React.useEffect(() => () => clearTimeout(leave.current), []);
  const enter = () => { clearTimeout(leave.current); setHot(true); };
  const out = () => { clearTimeout(leave.current); leave.current = setTimeout(() => setHot(false), LEAVE_MS); };
  const shown = total ?? line;
  return (
    // the window is a React child of this wrapper, so moving the pointer from the line into it is not a "leave"
    <div data-testid="reply-meta" data-open={open ? "1" : "0"} data-final={final ? "1" : "0"} onMouseEnter={enter} onMouseLeave={out} style={{ margin: "0 0 12px", fontFamily: font, fontSize: 10, color: k.dim }}>
      <button ref={trigger} data-testid="reply-meta-toggle" onClick={() => { setHot(false); setPin(!open); }}
        title={open ? "click to fold the details" : "hover to preview the details · click to keep them open"}
        style={{ background: "transparent", border: "none", padding: 0, cursor: "pointer", fontFamily: "inherit", fontSize: "inherit", color: open ? k.muted : k.dim, textAlign: "left", maxWidth: "100%" }}>
        {open ? "▾" : "⋯"} <span data-testid="reply-meta-line">{shown || "details"}</span>
      </button>
      {open && (
        <div data-testid="reply-meta-body" style={{ marginTop: 3, paddingLeft: 10, borderLeft: `1px solid ${k.border}`, display: "flex", flexDirection: "column", gap: 3 }}>
          {total && <div data-testid="reply-meta-last" style={{ color: k.dim }}>this turn · {line || "details"}</div>}
          {children}
        </div>
      )}
      {showPreview && pos && createPortal(
        <div data-testid="reply-meta-preview" style={{ position: "fixed", left: pos.left, top: pos.top, bottom: pos.bottom, width: pos.width, maxHeight: 340, overflowY: "auto", zIndex: 401, background: k.panel, color: k.fg, border: `1px solid ${k.border}`, borderRadius: 8, padding: "8px 10px", display: "flex", flexDirection: "column", gap: 4, boxShadow: "0 12px 34px rgba(0,0,0,.45)", fontFamily: font, fontSize: 10 }}>
          {children}
        </div>, document.body)}
    </div>
  );
}
